#include "field.hpp"
int main(){try{for(auto& p:PHYS)std::cin>>p.cap>>p.lm>>p.ls>>p.le>>p.m;State s;for(auto& z:s.z)std::cin>>z;int frozen,n;std::cin>>s.b>>s.q>>frozen>>n;s.phase=0;s.time=0;FREEZE_GAINS=frozen;std::vector<Pulse> in;for(int i=0;i<n;i++){Pulse p;std::cin>>p.time>>p.amp>>p.port;p.label=i;in.push_back(p);}std::sort(in.begin(),in.end(),[](auto a,auto b){return a.port!=b.port?a.port<b.port:a.time<b.time;});State end;double diag[8];auto out=cell_run(in,s,frozen,false,0,end,diag);std::cout<<std::setprecision(17)<<"{\"events\":[";for(size_t i=0;i<out.size();i++){if(i)std::cout<<",";std::cout<<out[i].time;}std::cout<<"],\"state\":";json_state(std::cout,end);std::cout<<"}";}catch(const std::exception& e){std::cerr<<e.what();return 1;}}
